import React, { useEffect, useState } from 'react';

function App() {
  const [risks, setRisks] = useState([]);

  useEffect(() => {
    fetch('/api/risks')
      .then(res => res.json())
      .then(data => setRisks(data))
      .catch(err => console.error(err));
  }, []);

  return (
    <div style={{ padding: '20px', fontFamily: 'Arial' }}>
      <h1>Risk Management Dashboard</h1>
      <table border="1" cellPadding="10">
        <thead>
          <tr>
            <th>ID</th>
            <th>Risk Name</th>
            <th>Severity</th>
          </tr>
        </thead>
        <tbody>
          {risks.map(risk => (
            <tr key={risk.id}>
              <td>{risk.id}</td>
              <td>{risk.name}</td>
              <td>{risk.severity}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

export default App;
